// Minimal fault handler sketch (C-like)
void handle_fault(Page* p){
  acquire(p->lock);
  if (p->present) { release(p->lock); return; }
  if (p->loading) { wait_on(p); release(p->lock); /* queue waiter */ return; }
  p->loading = true; release(p->lock);
  // IO or zero-fill
