// Pseudo C-like sketch for acquire/release
typedef struct Node { volatile int locked; struct Node *next; } Node;
typedef struct Lock { Node *tail; } MCSLock;
void lock_acquire(MCSLock *L, Node *me) {
  me->next = NULL; me->locked = 1;
  Node *pred = atomic_swap(&L->tail, me);
  if (pred) { pred->next = me; while (me->locked) pause(); }
}
void lock_release(MCSLock *L, Node *me) {
  if (!me->next) { if (atomic_compare_and_swap(&L->tail, me, NULL)) return; while (!me->next) pause(); }
  me->next->locked = 0;
}
```

